class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        base = sum(abs(a - b) for a, b in zip(nums1, nums2))
        t = nums2[-1]
        extra = min(min(abs(a - t), abs(b - t)) for a, b in zip(nums1, nums2))
        return base + 1 + extra

