class Solution {
public:
    long long minOperations(vector<int>& nums1, vector<int>& nums2) {
        long long base = 0;
        int t = nums2.back();
        int extra = INT_MAX;
        for (size_t i = 0; i < nums1.size(); i++) {
            base += abs(nums1[i] - nums2[i]);
            extra = min(extra, min(abs(nums1[i] - t), abs(nums2[i] - t)));
        }
        return base + 1 + extra;
    }
};

