class Solution {
    public long minOperations(int[] nums1, int[] nums2) {
        long base = 0;
        int t = nums2[nums2.length - 1];
        int extra = Integer.MAX_VALUE;
        for (int i = 0; i < nums1.length; i++) {
            base += Math.abs(nums1[i] - nums2[i]);
            extra = Math.min(extra, Math.min(Math.abs(nums1[i] - t), Math.abs(nums2[i] - t)));
        }
        return base + 1 + extra;
    }
}

